    {
      "id": "d-near",
      "semantic_distance": "near",
      "industry_role": "subject",
      "content_subject_hypothesis": "一个种了十五年果园的人，持续讲清楚水果从开花、剪枝、疏果、天气应对到采摘的具体判断和代价，让观众看见“果子为什么值得信任”。",
      "association_path_hypothesis": ["果农", "果园长期经营", "农活与节气观察", "方言短段子口述", "正脸一人一机记录", "观众把可信度归因到本人"],
      "structure_mapping_hypothesis": [
        {"source_edge": "果树要经过节气、天气和一轮轮人工管理，才结出可卖的果子", "target_edge": "账号要经过一次次真实出镜和具体农活讲述，才积累出可被信任的人设"},
