      ],
      "audience_tension_hypothesis": "观众想为可信的水果买单，又怕被田园滤镜或营销话术欺骗；想看真实农事，又不愿意看枯燥说教。",
      "expression_mode_hypothesis": "在果园现场用一部手机正脸拍摄，用带方言的短段子讲当下农活、天气和果树反应，不使用演员。",
      "subject_ownership": {
        "fact_refs": ["f1", "f3", "f4", "f5"],
        "hypothesis": "十五年经营提供真实的农活细节和时间感，方言短段子和正脸出镜让这些细节只能由他本人讲，一人一机在果园拍摄又强化了连续性。"
      },
      "business_attribution_hypothesis": "内容直接展示果子、果园和本人判断，观众未来看到桃子等果品时，容易归因到这个长期种果、正脸讲述的人。",
      "assumptions": ["果园日常有足够可讲的农活节点", "方言不会造成普遍理解障碍", "观众愿意长期跟随农事节奏"],
      "far_deletion_test": null
    },
    {
      "id": "d-mid",
      "semantic_distance": "mid",
      "industry_role": "metaphor",
      "content_subject_hypothesis": "普通人在关系、机会和责任面前因为舍不得剪、舍不得疏而把好事拖成消耗；每集用一个果园动作，对应一个“想全留却必须取舍”的人际决策。",
      "association_path_hypothesis": ["果园农活中的剪枝、疏果、等待", "这些动作里“舍不得就长不好”的因果边", "迁移到人在关系、机会、责任中的取舍", "用方言段子讲成具体人的处境", "观众在自己的生活里认出同一条因果边"],
      "structure_mapping_hypothesis": [
        {"source_edge": "果树枝条太密时不剪，会争抢光照和养分，最后果子反而长不大", "target_edge": "人在关系里什么都想抓住、不肯设边界，最后精力被分散，真正重要的人和事反而被拖累"},
        {"source_edge": "疏果时必须摘掉一些幼果，哪怕看起来可惜，才能让留下的果子长好", "target_edge": "人必须放弃一些看似不错的机会、情面或期待，才能守住少数真正重要的承诺"},
        {"source_edge": "遇到倒春寒或病虫害，管得再好也可能受损", "target_edge": "关系或计划遇到不可控变故时，人只能接受结果并重新修剪期待"}
      ],
      "audience_tension_hypothesis": "想做重情义、不拒绝的人，又发现精力和责任有限；想留住所有可能性，又必须舍弃一些才不把生活拖垮。",
      "expression_mode_hypothesis": "在果园里边做手边活边用方言讲短段子；前半段是农活，后半段转到一个普通人的取舍瞬间，用包袱代替道理。",
      "subject_ownership": {
        "fact_refs": ["f1", "f3", "f4", "f5"],
        "hypothesis": "十五年果园经验使隐喻有具体动作、节点和代价，而不是凭空感悟；方言讲述和正脸出镜让这种迁移带有他个人的节奏和可信度。"
      },
      "business_attribution_hypothesis": "观众记住的是他从种果树里练出的取舍判断力和耐心，这种人格信任再回流到果园产品，形成“人种得好、讲得真、果子可信”的归因。",
      "assumptions": ["农活因果和人际关系之间能建立自然对应", "他能把隐喻讲成段子而非鸡汤", "观众接受果园作为隐喻来源而不觉得生硬"],
      "far_deletion_test": null
    },
    {
      "id": "d-far",
      "semantic_distance": "far",
      "industry_role": "stage",
      "content_subject_hypothesis": "一个擅长用玩笑把难堪说出口的人，发现自己越会逗大家笑，越没人相信他也有认真和脆弱的时刻；他每次想认真说出需要，都会被笑声、接梗和“你别逗了”挡回去。",
      "association_path_hypothesis": ["果园作为固定取景舞台", "一个人正脸讲方言短段子", "段子里的人在借钱、随礼、聚会、道歉等场景试探认真", "听众继续用玩笑框架接收", "讲述者暴露玩笑背后的真实处境"],
      "structure_mapping_hypothesis": [
        {"source_edge": "讲笑话的人抛出轻巧包袱，听众用笑声确认“这只是玩笑”", "target_edge": "当他夹带真实态度或求助时，听众仍按旧框架理解，使真实信号失效"},
        {"source_edge": "他越擅长替别人把难堪变成笑料，别人越习惯向他索要情绪释放", "target_edge": "轮到他流露难处时，别人反而期待他继续搞笑，使他的脆弱被当作表演失误"},
        {"source_edge": "他为了维持关系继续接梗圆场", "target_edge": "对方得到了轻松，他却失去了被认真对待的机会"}
      ],
      "audience_tension_hypothesis": "想靠幽默和随和被喜欢，又渴望自己的真话被认真接住；怕一旦不搞笑就失去关注，又怕一直搞笑就永远不被理解。",
      "expression_mode_hypothesis": "一镜到底正脸口述，果园只是背景；用方言短段子和微型反转呈现不同社交场景，不依赖顾客、村民或家人出演。",
      "subject_ownership": {
        "fact_refs": ["f3", "f4"],
        "hypothesis": "他喜欢把观察讲成带方言短段子，且愿意正脸出镜，这让“玩笑与认真错位”可以通过他本人的语言节奏和表情持续验证，不需要职业身份提供情节。"
      },
      "business_attribution_hypothesis": "内容短期不直接卖水果，而是先让观众记住这个正脸、方言、会讲段子的人；长期靠稳定人设和后续果园信息露出，把人格信任迁移到果品，归因链路更长但人物辨识度可能更强。",
      "assumptions": ["他能在逗笑之外表现认真和脆弱", "观众愿意看无直接农事的普遍处境段子", "果园作为纯背景不会削弱人物辨识度", "长期积累后仍能完成产品归因"],
