        "removed_surface_terms": ["果农", "果园", "水果"],
        "remaining_human_subject_hypothesis": "一个习惯用方言段子化解难堪、却在自己认真时总被当成玩笑的人，如何在继续被喜欢和冒险说出真话之间反复选择。",
        "ownership_fact_refs": ["f3", "f4"]
      }
    }
